package cl.nexbyte.siger.institucional.documental;
import cl.nexbyte.siger.institucional.nucleo.*;import cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador;
import cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales;import cl.nexbyte.siger.institucional.formulario.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.util.*;import java.time.*;import java.io.*;import java.security.*;

/** Seguridad técnica puede aislar; ni el incidente ni su revisión conceden lectura funcional a TI. */
public final class CuarentenaDocumental {
 public record Aislar(UUID documento,String sha256,String referencia,String fundamento){@Override public String toString(){return "IncidenteTecnico[privado]";}}
 public record Verificar(long revision,String fundamento){@Override public String toString(){return "RevisionTecnica[privada]";}}
 public record Movimiento(long secuencia,String actor,Instant fecha,String tipo,String fundamento){}
 public record Incidente(UUID id,UUID documento,String sha256,long revision,String estado,String retenidoPor,Instant retenidoEn,
                         String referencia,String fundamento,String liberadoPor,Instant liberadoEn,boolean verificable,List<Movimiento> historial){}
 public record Pagina(List<Incidente> items,long total,int pagina,int limite){}
 private final BaseJdbc db;private final NucleoInstitucional core;private final CatalogoLaboratorio cat;private final AutoridadesInstitucionales autoridades;
 private final ArchivoInstitucional files;private final RecepcionInstitucionalJdbc receiver;private final ProcesamientoDocumental.Antivirus antivirus;private final ProcesamientoDocumental.Inspector inspector;private final Clock clock;
 public CuarentenaDocumental(BaseJdbc db,NucleoInstitucional core,CatalogoLaboratorio cat,AutoridadesInstitucionales autoridades,ArchivoInstitucional files,RecepcionInstitucionalJdbc receiver,ProcesamientoDocumental.Antivirus av,ProcesamientoDocumental.Inspector inspector,Clock clock){this.db=db;this.core=core;this.cat=cat;this.autoridades=autoridades;this.files=files;this.receiver=receiver;this.antivirus=av;this.inspector=inspector;this.clock=clock;}
 private static String id(UUID v){if(v==null)throw new FalloTecnico(400);return v.toString();}
 private static String s(Map<String,Object> r,String k){return Objects.toString(r.get(k),null);}
 private static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 private static void texto(String v,int max){try{cl.nexbyte.siger.contrato.DeclaracionNna.texto(v,max,true);}catch(IllegalArgumentException e){throw new FalloTecnico(400);}}
 private static String hash(Object v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(EntregaCompleta.lector().writeValueAsBytes(v)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 private String actor(Operador a){if(!cat.individual())throw new FalloTecnico(409,"IDENTIDAD_INDIVIDUAL_REQUERIDA");core.bloquearAcceso(a);if(!a.ti())throw new FalloTecnico(403);if(!DisponibilidadDocumental.esquema(db))throw new FalloTecnico(409,"ESQUEMA_DOCUMENTAL_NO_DISPONIBLE");return autoridades.contextoFunciones(a.id()).persona();}
 private Map<String,Object> fila(UUID hold){var rows=db.sql.queryForList("SELECT * FROM document_technical_hold WHERE id=?",id(hold));if(rows.isEmpty())throw new FalloTecnico(404);return rows.getFirst();}
 private Map<String,Object> documento(UUID doc,boolean lock){var rows=db.sql.queryForList("SELECT * FROM institution_document WHERE id=?"+(lock?" FOR UPDATE":""),id(doc));if(rows.size()!=1)throw new FalloTecnico(404);return rows.getFirst();}
 private EntregaCompleta.Adjunto descriptor(Map<String,Object> d){UUID doc=UUID.fromString(s(d,"id"));if("INGRESO_CIUDADANO".equals(d.get("origin"))){var e=receiver.completaRegistrada(UUID.fromString(s(d,"communication_id")));var a=e.adjuntos().stream().filter(x->x.id().toString().equals(d.get("attachment_id"))).findFirst().orElseThrow(()->new FalloTecnico(409,"INTEGRIDAD_DOCUMENTAL_INVALIDA"));if(!a.sha256().equals(d.get("sha256")))throw new FalloTecnico(409,"INTEGRIDAD_DOCUMENTAL_INVALIDA");return a;}
  if(!"GESTION_INSTITUCIONAL".equals(d.get("origin"))||!("gestion/"+doc).equals(d.get("storage_key"))||d.get("created_by")==null)throw new FalloTecnico(409,"INTEGRIDAD_DOCUMENTAL_INVALIDA");return new EntregaCompleta.Adjunto(doc,s(d,"name"),n(d,"size_bytes"),s(d,"sha256"),s(d,"media_type"),"VALIDADO");}
 private UUID anterior(Operador a,UUID key,String operation,String digest){var rows=db.sql.queryForList("SELECT * FROM document_technical_command WHERE id=?",id(key));if(rows.isEmpty())return null;var c=rows.getFirst();if(!a.id().equals(c.get("actor_id"))||!operation.equals(c.get("operation_code"))||!digest.equals(c.get("request_hash")))throw new FalloTecnico(409);return UUID.fromString(s(c,"hold_id"));}
 private void comando(Operador a,UUID key,UUID hold,String op,String digest){db.sql.update("INSERT INTO document_technical_command VALUES(?,?,?,?,?)",id(key),a.id(),id(hold),op,digest);}
 private void evento(Operador a,UUID hold,String code,String reason){db.sql.update("INSERT INTO document_technical_history(hold_id,actor_id,at_ms,event_code,reason_text) VALUES(?,?,?,?,?)",hold==null?null:id(hold),a.id(),clock.millis(),code,reason);}
 private Incidente vista(Map<String,Object> r,String persona,boolean historia){UUID hold=UUID.fromString(s(r,"id"));var list=historia?db.sql.queryForList("SELECT seq,actor_id,at_ms,event_code,reason_text FROM document_technical_history WHERE hold_id=? ORDER BY seq DESC LIMIT 100",id(hold)).stream().map(h->new Movimiento(n(h,"seq"),s(h,"actor_id"),Instant.ofEpochMilli(n(h,"at_ms")),s(h,"event_code"),s(h,"reason_text"))).toList():List.<Movimiento>of();return new Incidente(hold,UUID.fromString(s(r,"document_id")),s(r,"source_sha256"),n(r,"revision"),s(r,"state"),s(r,"held_by"),Instant.ofEpochMilli(n(r,"held_ms")),s(r,"incident_reference"),s(r,"reason_text"),s(r,"released_by"),r.get("released_ms")==null?null:Instant.ofEpochMilli(n(r,"released_ms")),"RETENIDO".equals(r.get("state"))&&!persona.equals(r.get("held_person")),list);}
 public Pagina listar(Operador a,String estado,int pagina,int limite){if(!Set.of("RETENIDO","LIBERADO").contains(estado)||pagina<0||pagina>1000000||limite<1||limite>100)throw new FalloTecnico(400);return db.transaction(()->{String person=actor(a);long total=db.sql.queryForObject("SELECT COUNT(*) FROM document_technical_hold WHERE state=?",Long.class,estado);var list=db.sql.queryForList("SELECT * FROM document_technical_hold WHERE state=? ORDER BY held_ms DESC,id LIMIT ? OFFSET ?",estado,limite,(long)pagina*limite).stream().map(r->vista(r,person,false)).toList();evento(a,null,"CUARENTENAS_LISTADAS",null);return new Pagina(list,total,pagina,limite);});}
 public Incidente ver(Operador a,UUID hold){return db.transaction(()->{String person=actor(a);var r=fila(hold);evento(a,hold,"CUARENTENA_CONSULTADA",null);return vista(r,person,true);});}
 public Incidente aislar(Operador a,UUID key,Aislar r){if(r==null||r.documento()==null||r.sha256()==null||!r.sha256().matches("[a-f0-9]{64}"))throw new FalloTecnico(400);texto(r.referencia(),500);texto(r.fundamento(),2000);String digest=hash(List.of("CUARENTENA_1",r));return db.transaction(()->{
  String person=actor(a);UUID previous=anterior(a,key,"AISLAR",digest);if(previous!=null)return vista(fila(previous),person,true);var d=documento(r.documento(),true);var desc=descriptor(d);if(!desc.sha256().equals(r.sha256()))throw new FalloTecnico(404);if(DisponibilidadDocumental.retenido(db,r.documento()))throw new FalloTecnico(409,"DOCUMENTO_YA_AISLADO");UUID hold=UUID.randomUUID();
  db.sql.update("INSERT INTO document_technical_hold(id,document_id,active_document_id,revision,state,source_sha256,held_by,held_person,held_ms,reason_text,incident_reference) VALUES(?,?,?,0,'RETENIDO',?,?,?,?,?,?)",id(hold),id(r.documento()),id(r.documento()),r.sha256(),a.id(),person,clock.millis(),r.fundamento(),r.referencia());evento(a,hold,"DOCUMENTO_AISLADO",r.fundamento());comando(a,key,hold,"AISLAR",digest);return vista(fila(hold),person,true);
 });}
 public Incidente verificar(Operador a,UUID key,UUID hold,Verificar r){if(r==null||r.revision()<0)throw new FalloTecnico(400);texto(r.fundamento(),2000);String digest=hash(List.of("LIBERAR_DOCUMENTO_1",hold,r));
  var initial=db.transaction(()->{actor(a);UUID previous=anterior(a,key,"VERIFICAR",digest);if(previous!=null){if(!previous.equals(hold))throw new FalloTecnico(409);return Map.<String,Object>of("reintento",true);}var h=fila(hold);revisable(a,h,r.revision());var d=documento(UUID.fromString(s(h,"document_id")),true);if(!s(h,"source_sha256").equals(descriptor(d).sha256()))throw new FalloTecnico(409,"INTEGRIDAD_DOCUMENTAL_INVALIDA");evento(a,hold,"VERIFICACION_INICIADA",null);return d;});
  if(initial.containsKey("reintento"))return ver(a,hold);
  try{var desc=descriptor(initial);var path=files.verificar(s(initial,"storage_key"),desc);if(!antivirus.limpio(path))throw new FalloTecnico(422,"DOCUMENTO_SIGUE_AISLADO");var ext=FormatosDocumento.extension(desc.nombre());if(!desc.tipo().equals(inspector.examinar(path,ext).tipo()))throw new IllegalArgumentException();files.verificar(s(initial,"storage_key"),desc);}
  catch(IOException|IllegalArgumentException e){fallo(a,hold);throw new FalloTecnico(503,"VERIFICACION_NO_COMPLETADA");}catch(FalloTecnico e){fallo(a,hold);throw e;}
  try{return db.transaction(()->{String person=actor(a);UUID previous=anterior(a,key,"VERIFICAR",digest);if(previous!=null){if(!previous.equals(hold))throw new FalloTecnico(409);return vista(fila(hold),person,true);}var h=fila(hold);revisable(a,h,r.revision());var d=documento(UUID.fromString(s(h,"document_id")),true);if(!s(h,"source_sha256").equals(descriptor(d).sha256()))throw new FalloTecnico(409,"INTEGRIDAD_DOCUMENTAL_INVALIDA");
   db.sql.update("UPDATE document_technical_hold SET state='LIBERADO',active_document_id=NULL,revision=revision+1,released_by=?,released_person=?,released_ms=?,release_reason=?,verification_profile='VERIFICACION_PRIVADA_1.0' WHERE id=?",a.id(),person,clock.millis(),r.fundamento(),id(hold));evento(a,hold,"DOCUMENTO_LIBERADO",r.fundamento());comando(a,key,hold,"VERIFICAR",digest);return vista(fila(hold),person,true);
  });}catch(RuntimeException|Error failed){try{fallo(a,hold);}catch(RuntimeException|Error audit){failed.addSuppressed(audit);}throw failed;}
 }
 private void revisable(Operador a,Map<String,Object> h,long revision){String person=actor(a);if(person.equals(h.get("held_person")))throw new FalloTecnico(403,"REVISION_TECNICA_INDEPENDIENTE_REQUERIDA");if(!"RETENIDO".equals(h.get("state"))||n(h,"revision")!=revision)throw new FalloTecnico(409,"VERSION_OBSOLETA");}
 private void fallo(Operador a,UUID hold){db.transaction(()->{evento(a,hold,"VERIFICACION_NO_COMPLETADA",null);return null;});}
}
